330 // Implementations for CD3DX12FeatureSupport functions
331 
332 // Macro to set up a getter function for each entry in feature support data
333 // The getter function will have the same name as the feature option name
334 #define FEATURE_SUPPORT_GET(RETTYPE,FEATURE,OPTION) \
335 inline RETTYPE CD3DX12FeatureSupport::OPTION() const noexcept \
336 { \
337     return FEATURE.OPTION; \
338 }
339 
340 // Macro to set up a getter function for each entry in feature support data
341 // Also specifies the name for the function which can be different from the feature name
342 #define FEATURE_SUPPORT_GET_NAME(RETTYPE,FEATURE,OPTION,NAME) \
343 inline RETTYPE CD3DX12FeatureSupport::NAME() const noexcept \
344 {\
345     return FEATURE.OPTION; \
346 }
347 
348 // Macro to set up a getter function for feature data indexed by the graphics node ID
349 // The default parameter is 0, or the first availabe graphics device node
350 #define FEATURE_SUPPORT_GET_NODE_INDEXED(RETTYPE,FEATURE,OPTION) \
351 inline RETTYPE CD3DX12FeatureSupport::OPTION(UINT NodeIndex) const \
352 {\
353     return FEATURE[NodeIndex].OPTION; \
354 }
355 
356 // Macro to set up a getter function for feature data indexed by NodeIndex
357 // Allows a custom name for the getter function
358 #define FEATURE_SUPPORT_GET_NODE_INDEXED_NAME(RETTYPE,FEATURE,OPTION,NAME) \
359 inline RETTYPE CD3DX12FeatureSupport::NAME(UINT NodeIndex) const \
360 {\
361     return FEATURE[NodeIndex].OPTION; \
362 }
