424 inline HRESULT CD3DX12FeatureSupport::Init(ID3D12Device* pDevice)
425 {
426     if (!pDevice)
427     {
428         m_hStatus = E_INVALIDARG;
429         return m_hStatus;
430     }
431 
432     m_pDevice = pDevice;
433 
434     // Initialize static feature support data structures
435     if (FAILED(m_pDevice->CheckFeatureSupport(D3D12_FEATURE_D3D12_OPTIONS, &m_dOptions, sizeof(m_dOptions))))
436     {
437         m_dOptions = {};
438     }
439 
440     if (FAILED(m_pDevice->CheckFeatureSupport(D3D12_FEATURE_GPU_VIRTUAL_ADDRESS_SUPPORT, &m_dGPUVASupport, sizeof(m_dGPUVASupport))))
441     {
442         m_dGPUVASupport = {};
443     }
444 
445     if (FAILED(m_pDevice->CheckFeatureSupport(D3D12_FEATURE_D3D12_OPTIONS1, &m_dOptions1, sizeof(m_dOptions1))))
446     {
447         m_dOptions1 = {};
448     }
449 
450     if (FAILED(m_pDevice->CheckFeatureSupport(D3D12_FEATURE_D3D12_OPTIONS2, &m_dOptions2, sizeof(m_dOptions2))))
451     {
452         m_dOptions2 = {};
453     }
454 
455     if (FAILED(m_pDevice->CheckFeatureSupport(D3D12_FEATURE_SHADER_CACHE, &m_dShaderCache, sizeof(m_dShaderCache))))
456     {
457         m_dShaderCache = {};
458     }
459 
