535     if (FAILED(m_pDevice->CheckFeatureSupport(D3D12_FEATURE_D3D12_OPTIONS13, &m_dOptions13, sizeof(m_dOptions13))))
536     {
537         m_dOptions13 = {};
538     }
539 #endif
540 
541 #if defined(D3D12_SDK_VERSION) && (D3D12_SDK_VERSION >= 606)
542     if (FAILED(m_pDevice->CheckFeatureSupport(D3D12_FEATURE_D3D12_OPTIONS14, &m_dOptions14, sizeof(m_dOptions14))))
543     {
544         m_dOptions14 = {};
545     }
546 
547     if (FAILED(m_pDevice->CheckFeatureSupport(D3D12_FEATURE_D3D12_OPTIONS15, &m_dOptions15, sizeof(m_dOptions15))))
548     {
549         m_dOptions15 = {};
550     }
551 #endif
552 
553 #if defined(D3D12_SDK_VERSION) && (D3D12_SDK_VERSION >= 608)
554     if (FAILED(m_pDevice->CheckFeatureSupport(D3D12_FEATURE_D3D12_OPTIONS16, &m_dOptions16, sizeof(m_dOptions16))))
555     {
556         m_dOptions16 = {};
557     }
558 #endif
559 
560 #if defined(D3D12_SDK_VERSION) && (D3D12_SDK_VERSION >= 609)
561     if (FAILED(m_pDevice->CheckFeatureSupport(D3D12_FEATURE_D3D12_OPTIONS17, &m_dOptions17, sizeof(m_dOptions17))))
562     {
563         m_dOptions17 = {};
564     }
565 
566     if (FAILED(m_pDevice->CheckFeatureSupport(D3D12_FEATURE_D3D12_OPTIONS18, &m_dOptions18, sizeof(m_dOptions18))))
567     {
568         m_dOptions18.RenderPassesValid = false;
569     }
570 #endif
571 
572 #if defined(D3D12_SDK_VERSION) && (D3D12_SDK_VERSION >= 610)
573     if (FAILED(m_pDevice->CheckFeatureSupport(D3D12_FEATURE_D3D12_OPTIONS19, &m_dOptions19, sizeof(m_dOptions19))))
574     {
575         m_dOptions19 = {};
576         m_dOptions19.SupportedSampleCountsWithNoOutputs = 1;
577         m_dOptions19.MaxSamplerDescriptorHeapSize = D3D12_MAX_SHADER_VISIBLE_SAMPLER_HEAP_SIZE;
578         m_dOptions19.MaxSamplerDescriptorHeapSizeWithStaticSamplers = D3D12_MAX_SHADER_VISIBLE_SAMPLER_HEAP_SIZE;
579         m_dOptions19.MaxViewDescriptorHeapSize = D3D12_MAX_SHADER_VISIBLE_DESCRIPTOR_HEAP_SIZE_TIER_1;
580     }
581 #endif
582 
583 #if defined(D3D12_SDK_VERSION) && (D3D12_SDK_VERSION >= 611)
584     if (FAILED(m_pDevice->CheckFeatureSupport(D3D12_FEATURE_D3D12_OPTIONS20, &m_dOptions20, sizeof(m_dOptions20))))
585     {
586         m_dOptions20 = {};
587     }
588 #endif
589 
590 #if defined(D3D12_SDK_VERSION) && (D3D12_SDK_VERSION >= 612)
591     if (FAILED(m_pDevice->CheckFeatureSupport(D3D12_FEATURE_D3D12_OPTIONS21, &m_dOptions21, sizeof(m_dOptions21))))
592     {
593         m_dOptions21 = {};
594     }
595 #endif
596 
597     // Initialize per-node feature support data structures
598     const UINT uNodeCount = m_pDevice->GetNodeCount();
599     m_dProtectedResourceSessionSupport.resize(uNodeCount);
600     m_dArchitecture1.resize(uNodeCount);
601     m_dSerialization.resize(uNodeCount);
602     m_dProtectedResourceSessionTypeCount.resize(uNodeCount);
603     m_dProtectedResourceSessionTypes.resize(uNodeCount);
604     for (UINT NodeIndex = 0; NodeIndex < uNodeCount; NodeIndex++)
605     {
606         m_dProtectedResourceSessionSupport[NodeIndex].NodeIndex = NodeIndex;
607         if (FAILED(m_pDevice->CheckFeatureSupport(D3D12_FEATURE_PROTECTED_RESOURCE_SESSION_SUPPORT, &m_dProtectedResourceSessionSupport[NodeIndex], sizeof(m_dProtectedResourceSessionSupport[NodeIndex]))))
608         {
609             m_dProtectedResourceSessionSupport[NodeIndex].Support = D3D12_PROTECTED_RESOURCE_SESSION_SUPPORT_FLAG_NONE;
610         }
611 
612         m_dArchitecture1[NodeIndex].NodeIndex = NodeIndex;
613         if (FAILED(m_pDevice->CheckFeatureSupport(D3D12_FEATURE_ARCHITECTURE1, &m_dArchitecture1[NodeIndex], sizeof(m_dArchitecture1[NodeIndex]))))
614         {
615             D3D12_FEATURE_DATA_ARCHITECTURE dArchLocal = {};
616             dArchLocal.NodeIndex = NodeIndex;
617             if (FAILED(m_pDevice->CheckFeatureSupport(D3D12_FEATURE_ARCHITECTURE, &dArchLocal, sizeof(dArchLocal))))
618             {
619                 dArchLocal.TileBasedRenderer = false;
620                 dArchLocal.UMA = false;
621                 dArchLocal.CacheCoherentUMA = false;
622             }
623 
624             m_dArchitecture1[NodeIndex].TileBasedRenderer = dArchLocal.TileBasedRenderer;
625             m_dArchitecture1[NodeIndex].UMA = dArchLocal.UMA;
626             m_dArchitecture1[NodeIndex].CacheCoherentUMA = dArchLocal.CacheCoherentUMA;
627             m_dArchitecture1[NodeIndex].IsolatedMMU = false;
628         }
629 
630         m_dSerialization[NodeIndex].NodeIndex = NodeIndex;
631         if (FAILED(m_pDevice->CheckFeatureSupport(D3D12_FEATURE_SERIALIZATION, &m_dSerialization[NodeIndex], sizeof(m_dSerialization[NodeIndex]))))
632         {
633             m_dSerialization[NodeIndex].HeapSerializationTier = D3D12_HEAP_SERIALIZATION_TIER_0;
634         }
635 
636         m_dProtectedResourceSessionTypeCount[NodeIndex].NodeIndex = NodeIndex;
637         if (FAILED(m_pDevice->CheckFeatureSupport(D3D12_FEATURE_PROTECTED_RESOURCE_SESSION_TYPE_COUNT, &m_dProtectedResourceSessionTypeCount[NodeIndex], sizeof(m_dProtectedResourceSessionTypeCount[NodeIndex]))))
638         {
639             m_dProtectedResourceSessionTypeCount[NodeIndex].Count = 0;
640         }
641 
642         // Special procedure to initialize local protected resource session types structs
643         // Must wait until session type count initialized
644         QueryProtectedResourceSessionTypes(NodeIndex, m_dProtectedResourceSessionTypeCount[NodeIndex].Count);
645     }
646 
647     // Initialize features that requires highest version check
648     if (FAILED(m_hStatus = QueryHighestShaderModel()))
649     {
650         return m_hStatus;
651     }
652 
653     if (FAILED(m_hStatus = QueryHighestRootSignatureVersion()))
654     {
655         return m_hStatus;
656     }
657 
658     // Initialize Feature Levels data
659     if (FAILED(m_hStatus = QueryHighestFeatureLevel()))
660     {
661         return m_hStatus;
662     }
663 
664     return m_hStatus;
665 }
