718 inline HRESULT CD3DX12FeatureSupport::FormatSupport(DXGI_FORMAT Format, D3D12_FORMAT_SUPPORT1& Support1, D3D12_FORMAT_SUPPORT2& Support2) const
719 {
720     D3D12_FEATURE_DATA_FORMAT_SUPPORT dFormatSupport;
721     dFormatSupport.Format = Format;
722 
723     // It is possible that the function call returns an error
724     HRESULT result = m_pDevice->CheckFeatureSupport(D3D12_FEATURE_FORMAT_SUPPORT, &dFormatSupport, sizeof(D3D12_FEATURE_DATA_FORMAT_SUPPORT));
725 
726     Support1 = dFormatSupport.Support1;
727     Support2 = dFormatSupport.Support2; // Two outputs. Probably better just to take in the struct as an argument?
