975 // Helper function to decide the highest shader model supported by the system
976 // Stores the result in m_dShaderModel
977 // Must be updated whenever a new shader model is added to the d3d12.h header
978 inline HRESULT CD3DX12FeatureSupport::QueryHighestShaderModel()
979 {
980     // Check support in descending order
981     HRESULT result;
982 
983     const D3D_SHADER_MODEL allModelVersions[] =
984     {
985 #if defined(D3D12_SDK_VERSION) && (D3D12_SDK_VERSION >= 612)
986         D3D_SHADER_MODEL_6_9,
987 #endif
988 #if defined(D3D12_SDK_VERSION) && (D3D12_SDK_VERSION >= 606)
989         D3D_SHADER_MODEL_6_8,
990 #endif
991 #if defined(D3D12_SDK_VERSION) && (D3D12_SDK_VERSION >= 3)
992         D3D_SHADER_MODEL_6_7,
993 #endif
994         D3D_SHADER_MODEL_6_6,
995         D3D_SHADER_MODEL_6_5,
996         D3D_SHADER_MODEL_6_4,
997         D3D_SHADER_MODEL_6_3,
998         D3D_SHADER_MODEL_6_2,
999         D3D_SHADER_MODEL_6_1,
1000         D3D_SHADER_MODEL_6_0,
1001         D3D_SHADER_MODEL_5_1
1002     };
1003     constexpr size_t numModelVersions = sizeof(allModelVersions) / sizeof(D3D_SHADER_MODEL);
1004 
1005     for (size_t i = 0; i < numModelVersions; i++)
1006     {
1007         m_dShaderModel.HighestShaderModel = allModelVersions[i];
1008         result = m_pDevice->CheckFeatureSupport(D3D12_FEATURE_SHADER_MODEL, &m_dShaderModel, sizeof(D3D12_FEATURE_DATA_SHADER_MODEL));
1009         if (result != E_INVALIDARG)
1010         {
1011             // Indicates that the version is recognizable by the runtime and stored in the struct
1012             // Also terminate on unexpected error code
1013             if (FAILED(result))
1014             {
1015                 m_dShaderModel.HighestShaderModel = static_cast<D3D_SHADER_MODEL>(0);
1016             }
1017             return result;
1018         }
1019     }
1020 
1021     // Shader model may not be supported. Continue the rest initializations
1022     m_dShaderModel.HighestShaderModel = static_cast<D3D_SHADER_MODEL>(0);
1023     return S_OK;
1024 }
1025 
1026 // Helper function to decide the highest root signature supported
1027 // Must be updated whenever a new root signature version is added to the d3d12.h header
1028 inline HRESULT CD3DX12FeatureSupport::QueryHighestRootSignatureVersion()
1029 {
1030     HRESULT result;
1031 
1032     const D3D_ROOT_SIGNATURE_VERSION allRootSignatureVersions[] =
1033     {
1034 #if defined(D3D12_SDK_VERSION) && (D3D12_SDK_VERSION >= 609)
1035         D3D_ROOT_SIGNATURE_VERSION_1_2,
1036 #endif
1037         D3D_ROOT_SIGNATURE_VERSION_1_1,
1038         D3D_ROOT_SIGNATURE_VERSION_1_0,
1039         D3D_ROOT_SIGNATURE_VERSION_1,
1040     };
1041     constexpr size_t numRootSignatureVersions = sizeof(allRootSignatureVersions) / sizeof(D3D_ROOT_SIGNATURE_VERSION);
1042 
1043     for (size_t i = 0; i < numRootSignatureVersions; i++)
1044     {
1045         m_dRootSignature.HighestVersion = allRootSignatureVersions[i];
1046         result = m_pDevice->CheckFeatureSupport(D3D12_FEATURE_ROOT_SIGNATURE, &m_dRootSignature, sizeof(D3D12_FEATURE_DATA_ROOT_SIGNATURE));
1047         if (result != E_INVALIDARG)
1048         {
1049             if (FAILED(result))
1050             {
1051                 m_dRootSignature.HighestVersion = static_cast<D3D_ROOT_SIGNATURE_VERSION>(0);
1052             }
1053             // If succeeded, the highest version is already written into the member struct
1054             return result;
1055         }
1056     }
1057 
1058     // No version left. Set to invalid value and continue.
1059     m_dRootSignature.HighestVersion = static_cast<D3D_ROOT_SIGNATURE_VERSION>(0);
1060     return S_OK;
1061 }
1062 
1063 // Helper funcion to decide the highest feature level
1064 inline HRESULT CD3DX12FeatureSupport::QueryHighestFeatureLevel()
1065 {
1066     HRESULT result;
1067 
1068     // Check against a list of all feature levels present in d3dcommon.h
1069     // Needs to be updated for future feature levels
1070     const D3D_FEATURE_LEVEL allLevels[] =
1071     {
1072 #if defined(D3D12_SDK_VERSION) && (D3D12_SDK_VERSION >= 3)
1073         D3D_FEATURE_LEVEL_12_2,
1074 #endif
1075         D3D_FEATURE_LEVEL_12_1,
1076         D3D_FEATURE_LEVEL_12_0,
1077         D3D_FEATURE_LEVEL_11_1,
1078         D3D_FEATURE_LEVEL_11_0,
1079         D3D_FEATURE_LEVEL_10_1,
1080         D3D_FEATURE_LEVEL_10_0,
1081         D3D_FEATURE_LEVEL_9_3,
1082         D3D_FEATURE_LEVEL_9_2,
1083         D3D_FEATURE_LEVEL_9_1,
1084 #if defined(D3D12_SDK_VERSION) && (D3D12_SDK_VERSION >= 5)
1085         D3D_FEATURE_LEVEL_1_0_CORE,
1086 #endif
1087 #if defined(D3D12_SDK_VERSION) && (D3D12_SDK_VERSION >= 611)
1088         D3D_FEATURE_LEVEL_1_0_GENERIC
1089 #endif
1090     };
1091 
1092     D3D12_FEATURE_DATA_FEATURE_LEVELS dFeatureLevel;
1093     dFeatureLevel.NumFeatureLevels = static_cast<UINT>(sizeof(allLevels) / sizeof(D3D_FEATURE_LEVEL));
1094     dFeatureLevel.pFeatureLevelsRequested = allLevels;
1095 
1096     result = m_pDevice->CheckFeatureSupport(D3D12_FEATURE_FEATURE_LEVELS, &dFeatureLevel, sizeof(D3D12_FEATURE_DATA_FEATURE_LEVELS));
1097     if (SUCCEEDED(result))
1098     {
1099         m_eMaxFeatureLevel = dFeatureLevel.MaxSupportedFeatureLevel;
1100     }
1101     else
1102     {
1103         m_eMaxFeatureLevel = static_cast<D3D_FEATURE_LEVEL>(0);
1104 
1105         if (result == DXGI_ERROR_UNSUPPORTED)
1106         {
1107             // Indicates that none supported. Continue initialization
1108             result = S_OK;
1109         }
1110     }
1111     return result;
1112 }
1113 
1114 // Helper function to initialize local protected resource session types structs
1115 inline HRESULT CD3DX12FeatureSupport::QueryProtectedResourceSessionTypes(UINT NodeIndex, UINT Count)
1116 {
1117     auto& CurrentPRSTypes = m_dProtectedResourceSessionTypes[NodeIndex];
1118     CurrentPRSTypes.NodeIndex = NodeIndex;
1119     CurrentPRSTypes.Count = Count;
1120     CurrentPRSTypes.TypeVec.resize(CurrentPRSTypes.Count);
1121     CurrentPRSTypes.pTypes = CurrentPRSTypes.TypeVec.data();
1122 
1123     HRESULT result = m_pDevice->CheckFeatureSupport(D3D12_FEATURE_PROTECTED_RESOURCE_SESSION_TYPES, &m_dProtectedResourceSessionTypes[NodeIndex], sizeof(D3D12_FEATURE_DATA_PROTECTED_RESOURCE_SESSION_TYPES));
1124     if (FAILED(result))
1125     {
1126         // Resize TypeVec to empty
1127         CurrentPRSTypes.TypeVec.clear();
1128     }
1129 
1130     return result;
1131 }
